def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0.0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('budget', 0) > 300:
                rich_pressure += 1.0

    if budget <= 0:
        return 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    elif ample_supply:
        urgency -= 1
    if day >= 8:
        urgency += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
    elif urgency >= 7:
        base = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif urgency >= 5:
        base = max(DAILY_SALARY * 0.78, avg_prev + 2.0)
    elif urgency >= 3:
        if highest_prev >= 120:
            base = DAILY_SALARY * 0.52
        else:
            base = max(DAILY_SALARY * 0.48, avg_prev + 1.0)
    else:
        if highest_prev >= 120:
            base = DAILY_SALARY * 0.22
        elif highest_prev >= 90:
            base = DAILY_SALARY * 0.30
        else:
            base = DAILY_SALARY * 0.42

    if rich_pressure >= 2 and urgency <= 3:
        base *= 0.9
    if ample_supply and urgency <= 3:
        base *= 0.9
    if tight_supply and urgency >= 3:
        base *= 1.08

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = DAILY_SALARY * 2.0
    elif hp > 2:
        reserve = DAILY_SALARY * 1.0

    cap = budget - reserve
    if urgency >= 5:
        cap = budget
    if cap < 0:
        cap = min(budget, DAILY_SALARY * 0.4)

    bid = min(base, cap, budget)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.95, highest_prev + 2.5))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    base_bid = DAILY_SALARY * 0.55

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.98
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.75
    elif my_status['hp'] >= 8:
        base_bid = DAILY_SALARY * 0.45

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif day_context['day'] <= 2 and my_status['hp'] >= 8:
        base_bid = min(base_bid, DAILY_SALARY * 0.4)

    if highest_prev_bid > 0:
        if my_status['hp'] <= 4:
            if highest_prev_bid >= DAILY_SALARY * 0.7:
                base_bid = max(base_bid, highest_prev_bid + 5)
            else:
                base_bid = max(base_bid, highest_prev_bid + 1)
        else:
            if highest_prev_bid >= DAILY_SALARY * 0.8:
                base_bid = max(base_bid, highest_prev_bid * 0.95)
            elif highest_prev_bid >= DAILY_SALARY * 0.5:
                base_bid = max(base_bid, highest_prev_bid + 1)
            else:
                base_bid = min(base_bid, DAILY_SALARY * 0.6)

    final_bid = min(my_status['budget'], base_bid)
    final_bid = max(1.0, final_bid)

    if my_status['budget'] < DAILY_SALARY * 0.3 and my_status['hp'] <= 3:
        final_bid = my_status['budget']

    return final_bid

